"""OUR LEG — the cell we append to the public 0.943 blend notebook on Kaggle.

The public notebook itself is not copied into this repo; only this addition is ours.
It runs our own model_f*.pt over the test studies in a separate process, with a time
guard, and rank-blends the result into the public submission. If anything fails or
time runs short, the public submission is left untouched.
"""
import base64, os, subprocess, sys, time, numpy as np, pandas as pd
OUR_W = 0.15            # weight of our leg in the rank blend (0 = public only)
OUR_GLOB = "/kaggle/input/**/knee-models/**/model_f*.pt"
BUDGET_MIN = 525        # Kaggle limit is 540 min; leave a margin
_leg_dir = "/kaggle/working/our_leg"; os.makedirs(_leg_dir, exist_ok=True)
open(f"{_leg_dir}/leg.py", "w").write(base64.b64decode("").decode())
_left = BUDGET_MIN * 60 - (time.time() - T0)
print(f"time used so far {(time.time()-T0)/60:.0f} min, left for our leg {_left/60:.0f} min")
_ok = False
if OUR_W > 0 and _left > 20 * 60:
    _env = dict(os.environ, KNEE_MODEL_GLOB=OUR_GLOB, KNEE_OUT_DIR=_leg_dir, KNEE_OUT_NAME="ours.csv")
    try:
        r = subprocess.run([sys.executable, f"{_leg_dir}/leg.py"], env=_env, timeout=_left - 5 * 60,
                           capture_output=True, text=True)
        print(r.stdout[-3000:]); print(r.stderr[-3000:])
        _ok = r.returncode == 0 and os.path.exists(f"{_leg_dir}/ours.csv")
    except subprocess.TimeoutExpired:
        print("OUR LEG timed out -> keeping public submission")
if _ok:
    pub = pd.read_csv("/kaggle/working/submission.csv", dtype={"StudyInstanceUID": str})
    ours = pd.read_csv(f"{_leg_dir}/ours.csv", dtype={"StudyInstanceUID": str}).set_index("StudyInstanceUID").loc[pub.StudyInstanceUID]
    labs = [c for c in pub.columns if c != "StudyInstanceUID"]
    assert np.isfinite(ours[labs].to_numpy()).all()
    blend = pub.copy()
    for c in labs:
        rp = pub[c].rank(pct=True).to_numpy(); ro = ours[c].rank(pct=True).to_numpy()
        blend[c] = (1 - OUR_W) * rp + OUR_W * ro
    blend.to_csv("/kaggle/working/submission.csv", index=False)
    print(f"BLENDED with OUR_W={OUR_W} | corr per label:",
          {c: round(float(np.corrcoef(pub[c].rank(), ours[c].rank())[0, 1]), 2) for c in labs})
else:
    print("public submission kept unchanged")
